import { type Page, test } from "@playwright/test";

import * as ui from "@e2e/ui-actions";

const RESOLVE_LIBRARY_ID_USED = "Tool resolve-library-id used";
const ASK_QUESTION_USED = "Tool ask_question used";

const sendWithCollectFollowUps = async (page: Page, trigger: string, followUps: string[]) => {
  await ui.inspectorShell.actions(page).sendMessage(trigger);
  for (const reply of followUps) {
    await ui.inspectorShell.actions(page).sendMessage(reply);
  }
};

export const triggerDirectMcpSuccessAndAssertEvent = async (page: Page) => {
  await test.step("Send direct MCP success trigger with collect follow-ups", async () => {
    await sendWithCollectFollowUps(page, "inspector test direct mcp success", [
      "next.js",
      "middleware lookup",
    ]);
  });

  await test.step("Assert resolve-library-id MCP event in log", async () => {
    await ui.conversationLog.assertions(page).conversationEventReached(RESOLVE_LIBRARY_ID_USED);
  });
};

export const openMcpToolEventDetailsAndAssert = async (page: Page) => {
  await test.step("Click MCP tool event", async () => {
    await ui.conversationLog.actions(page).clickConversationEvent(RESOLVE_LIBRARY_ID_USED);
  });

  await test.step("Assert MCP tool executed panel", async () => {
    await ui.eventDetails.assertions(page).panelIsVisible("MCP tool executed");
    await ui.eventDetails.assertions(page).panelContainsText("resolve-library-id");
    await ui.eventDetails.assertions(page).mcpToolArgumentsVisible();
    await ui.eventDetails.assertions(page).mcpToolResultVisible();
  });
};

export const triggerContext7LookupAndAssertEvent = async (page: Page) => {
  await test.step("Ask for Context7 library id with collect follow-up", async () => {
    await sendWithCollectFollowUps(page, "What is the Context7 id for next.js?", [
      "library id lookup",
    ]);
  });

  await test.step("Assert resolve-library-id MCP event in log", async () => {
    await ui.conversationLog.assertions(page).conversationEventReached(RESOLVE_LIBRARY_ID_USED);
  });
};

export const triggerDeepWikiDirectMcpAndAssertEvent = async (page: Page) => {
  await test.step("Ask DeepWiki via MCP with collect follow-up", async () => {
    await sendWithCollectFollowUps(page, "Using MCP, what is rasaHQ/rasa?", [
      "How does routing work?",
    ]);
  });

  await test.step("Assert ask_question MCP event in log", async () => {
    await ui.conversationLog.assertions(page).conversationEventReached(ASK_QUESTION_USED);
  });
};
